'use strict';
class FlowRenderer {
  constructor(canvas,onState){
    this.canvas=canvas;this.onState=onState;this.edges=[];this.seen=new Map();this.packets=[];this.width=1280;this.height=740;this.zoom=1;this.pan=[0,0];this.paused=false;this.reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
    this.gl=canvas.getContext('webgl',{alpha:true,antialias:true,premultipliedAlpha:false,powerPreference:'low-power'});
    if(!this.gl){onState(false);return;}
    this.init();canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();cancelAnimationFrame(this.frame);this.onState(false);});canvas.addEventListener('webglcontextrestored',()=>{this.init();this.onState(true);this.tick();});
    this.onState(true);this.tick();
  }
  init(){const gl=this.gl;
    const vertex=`attribute vec2 aPos; attribute vec4 aColor; attribute float aSize; uniform vec2 uWorld; uniform vec2 uPixels; uniform vec2 uPan; uniform float uZoom; varying vec4 color; void main(){float scale=min(uPixels.x/uWorld.x,uPixels.y/uWorld.y); vec2 p=(aPos*uZoom+uPan-uWorld*.5)*scale; gl_Position=vec4(p.x/uPixels.x*2.,-p.y/uPixels.y*2.,0.,1.);gl_PointSize=aSize; color=aColor;}`;
    const fragment=`precision mediump float; varying vec4 color; uniform float uPoint; void main(){if(uPoint<.5){gl_FragColor=color;return;}vec2 p=gl_PointCoord*2.-1.;float r=length(p);if(r>1.)discard;float ball=1.-smoothstep(.42,.49,r);float z=sqrt(max(0.,1.-r*r/.2116));vec2 shine=p-vec2(-.12,-.14);float highlight=exp(-dot(shine,shine)*70.);float core=exp(-r*r*28.);vec3 sphere=color.rgb*(.60+.40*z)+vec3(1.)*highlight*.70;sphere=mix(sphere,vec3(1.),core*.58);vec3 rgb=mix(color.rgb,sphere,ball);float halo=exp(-r*r*6.)*.65;gl_FragColor=vec4(rgb,color.a*max(ball,halo));}`;
    const shader=(type,source)=>{const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw new Error('WebGL shader unavailable');return s;};
    const vs=shader(gl.VERTEX_SHADER,vertex),fs=shader(gl.FRAGMENT_SHADER,fragment);this.program=gl.createProgram();gl.attachShader(this.program,vs);gl.attachShader(this.program,fs);gl.linkProgram(this.program);gl.deleteShader(vs);gl.deleteShader(fs);if(!gl.getProgramParameter(this.program,gl.LINK_STATUS))throw new Error('WebGL link unavailable');
    this.buffer=gl.createBuffer();gl.useProgram(this.program);gl.bindBuffer(gl.ARRAY_BUFFER,this.buffer);
    for(const [name,size,offset]of [['aPos',2,0],['aColor',4,8],['aSize',1,24]]){const loc=gl.getAttribLocation(this.program,name);gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,size,gl.FLOAT,false,28,offset);}
    this.uWorld=gl.getUniformLocation(this.program,'uWorld');this.uPixels=gl.getUniformLocation(this.program,'uPixels');this.uPoint=gl.getUniformLocation(this.program,'uPoint');this.uPan=gl.getUniformLocation(this.program,'uPan');this.uZoom=gl.getUniformLocation(this.program,'uZoom');gl.enable(gl.BLEND);gl.blendFuncSeparate(gl.SRC_ALPHA,gl.ONE,gl.ONE,gl.ONE_MINUS_SRC_ALPHA);
    const bv=shader(gl.VERTEX_SHADER,`attribute vec2 aPos;attribute vec2 aLocal;attribute vec2 aBox;attribute vec4 aColor;uniform vec2 uWorld;uniform vec2 uPixels;uniform vec2 uPan;uniform float uZoom;varying vec2 local;varying vec2 box;varying vec4 color;void main(){float s=min(uPixels.x/uWorld.x,uPixels.y/uWorld.y);vec2 p=(aPos*uZoom+uPan-uWorld*.5)*s;gl_Position=vec4(p.x/uPixels.x*2.,-p.y/uPixels.y*2.,0.,1.);local=aLocal;box=aBox;color=aColor;}`);
    const bf=shader(gl.FRAGMENT_SHADER,`precision mediump float;varying vec2 local;varying vec2 box;varying vec4 color;void main(){vec2 q=abs(local)-(box*.5-vec2(5.));float d=length(max(q,0.))+min(max(q.x,q.y),0.)-5.;if(d>7.)discard;float border=1.-smoothstep(.6,1.7,abs(d));float glow=exp(-max(d,0.)*.65)*.15;float inside=1.-smoothstep(-.5,.5,d);vec3 bg=vec3(.035,.074,.095)+color.rgb*.028;float accent=step(local.x,-box.x*.5+3.)*inside;vec3 rgb=mix(bg,color.rgb,border*.7+accent*.65);float alpha=max(inside*.94,border*.7+glow);gl_FragColor=vec4(rgb,alpha);}`);
    this.boxProgram=gl.createProgram();gl.attachShader(this.boxProgram,bv);gl.attachShader(this.boxProgram,bf);gl.linkProgram(this.boxProgram);gl.deleteShader(bv);gl.deleteShader(bf);if(!gl.getProgramParameter(this.boxProgram,gl.LINK_STATUS))throw new Error('WebGL boxes unavailable');this.boxBuffer=gl.createBuffer();
  }
  setGraph(edges,width,height,nodes=[],liveIds=null){this.edges=edges;this.nodes=nodes;this.width=width;this.height=height;this.geometryDirty=true;const now=performance.now();const current=new Map();const scope=nodes[0]?.id;const sameScope=this.hasGraph&&this.scope===scope;if(!sameScope)this.packets=[];this.scope=scope;this.hasGraph=true;
    const edgeKey=e=>JSON.stringify([e.source?.id,e.target?.id,e.dashed]);const liveEdges=new Map(edges.map(e=>[edgeKey(e),e]));for(const packet of this.packets)packet.edge=liveEdges.get(edgeKey(packet.edge))||packet.edge;
    for(const e of edges){for(const event of (e.events||[e.event]).filter(Boolean).slice(-120)){if(event.evidence==='script')continue;const key=event.id+':'+event.status;current.set(key,true);if(!this.seen.has(key)&&(sameScope&&(!liveIds||liveIds.has(event.id))||Date.now()-Date.parse(event.completedAt||event.time)<15000))this.packets.push({edge:e,at:now,reverse:event.status==='completed'||event.status==='failed',failed:event.status==='failed'});}}
    this.seen=current;this.packets=this.packets.slice(-120);
  }
  buildLines(){const vertices=[];for(const e of this.visibleEdges||this.edges){for(let i=0;i<60;i++){const a=this.point(e,i/60),b=this.point(e,(i+1)/60),color=e.color||[.34,.88,.81];const alpha=e.dashed?.42:.75;if(e.dashed&&i%4>=2)continue;for(const p of [a,b])vertices.push(p[0],p[1],...color,alpha,1);}}this.lines=new Float32Array(vertices);}
  buildBoxes(){const out=[];const palette={task:[.34,.90,.82],skill:[.93,.77,.46],mcp:[.57,.88,.65],plugin:[.67,.58,1],tool:[.60,.68,.79]};for(const n of this.visibleNodes||this.nodes){const w=n.w/2+8,h=n.h/2+8;for(const [x,y]of [[-w,-h],[w,-h],[-w,h],[-w,h],[w,-h],[w,h]])out.push(n.x+n.w/2+x,n.y+n.h/2+y,x,y,n.w,n.h,...palette[n.kind],1);}this.boxes=new Float32Array(out);}
  setTransform(zoom,pan){if(this.zoom!==zoom||this.pan[0]!==pan[0]||this.pan[1]!==pan[1])this.geometryDirty=true;this.zoom=zoom;this.pan=[...pan];}
  refreshGeometry(w,h){if(!this.geometryDirty)return;const scale=Math.min(w/this.width,h/this.height);const left=(this.width/2-w/scale/2-this.pan[0])/this.zoom-30,right=(this.width/2+w/scale/2-this.pan[0])/this.zoom+30,top=(this.height/2-h/scale/2-this.pan[1])/this.zoom-30,bottom=(this.height/2+h/scale/2-this.pan[1])/this.zoom+30;this.visibleNodes=(this.nodes||[]).filter(n=>n.x+n.w>=left&&n.x<=right&&n.y+n.h>=top&&n.y<=bottom);this.visibleEdges=this.edges.filter(e=>TraceGraph.edgeVisible(e,{left,right,top,bottom}));this.visibleEdgeSet=new Set(this.visibleEdges);this.buildBoxes();this.buildLines();this.geometryDirty=false;}
  bindFlow(w,h){const gl=this.gl;gl.useProgram(this.program);gl.bindBuffer(gl.ARRAY_BUFFER,this.buffer);for(let i=0;i<gl.getParameter(gl.MAX_VERTEX_ATTRIBS);i++)gl.disableVertexAttribArray(i);for(const [name,size,offset]of [['aPos',2,0],['aColor',4,8],['aSize',1,24]]){const loc=gl.getAttribLocation(this.program,name);gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,size,gl.FLOAT,false,28,offset);}gl.uniform2f(this.uWorld,this.width,this.height);gl.uniform2f(this.uPixels,w,h);gl.uniform2f(this.uPan,...this.pan);gl.uniform1f(this.uZoom,this.zoom);}
  drawBoxes(w,h){const gl=this.gl;if(!this.boxes?.length)return;gl.useProgram(this.boxProgram);gl.bindBuffer(gl.ARRAY_BUFFER,this.boxBuffer);for(let i=0;i<gl.getParameter(gl.MAX_VERTEX_ATTRIBS);i++)gl.disableVertexAttribArray(i);for(const [name,size,offset]of [['aPos',2,0],['aLocal',2,8],['aBox',2,16],['aColor',4,24]]){const loc=gl.getAttribLocation(this.boxProgram,name);gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,size,gl.FLOAT,false,40,offset);}for(const [key,value]of [['uWorld',[this.width,this.height]],['uPixels',[w,h]],['uPan',this.pan]])gl.uniform2f(gl.getUniformLocation(this.boxProgram,key),...value);gl.uniform1f(gl.getUniformLocation(this.boxProgram,'uZoom'),this.zoom);gl.blendFuncSeparate(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA,gl.ONE,gl.ONE_MINUS_SRC_ALPHA);gl.bufferData(gl.ARRAY_BUFFER,this.boxes,gl.STATIC_DRAW);gl.drawArrays(gl.TRIANGLES,0,this.boxes.length/10);gl.blendFuncSeparate(gl.SRC_ALPHA,gl.ONE,gl.ONE,gl.ONE_MINUS_SRC_ALPHA);this.bindFlow(w,h);}
  point(e,t){const q=1-t;return [q*q*q*e.p0[0]+3*q*q*t*e.p1[0]+3*q*t*t*e.p2[0]+t*t*t*e.p3[0],q*q*q*e.p0[1]+3*q*q*t*e.p1[1]+3*q*t*t*e.p2[1]+t*t*t*e.p3[1]];}
  demoPulse(){if(!this.edges.length)return;const candidates=this.edges.filter(e=>!e.dashed);const e=candidates[Math.floor(Math.random()*candidates.length)];if(e)this.packets.push({edge:e,at:performance.now(),reverse:Math.random()>.5});}
  setPaused(paused){this.paused=paused;if(paused)this.packets=[];}
  tick(){this.frame=requestAnimationFrame(()=>this.tick());if(!this.gl||this.gl.isContextLost()||document.hidden)return;const now=performance.now();if(this.last&&now-this.last<30)return;this.last=now;
    const gl=this.gl,dpr=Math.min(devicePixelRatio||1,2),w=Math.round(this.canvas.clientWidth*dpr),h=Math.round(this.canvas.clientHeight*dpr);if(!w||!h)return;if(this.canvas.width!==w||this.canvas.height!==h){this.canvas.width=w;this.canvas.height=h;this.geometryDirty=true;}gl.viewport(0,0,w,h);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT);this.refreshGeometry(w,h);this.bindFlow(w,h);
    if(this.lines?.length){gl.uniform1f(this.uPoint,0);gl.bufferData(gl.ARRAY_BUFFER,this.lines,gl.STATIC_DRAW);gl.drawArrays(gl.LINES,0,this.lines.length/7);}
    this.drawBoxes(w,h);
    // Orbs carry the traffic signal. Reduced motion lowers density and speed.
    const duration=this.reduced?3800:2200;this.packets=this.packets.filter(p=>now-p.at<duration+200);if(this.paused)return;
    const points=[];for(const packet of this.reduced?this.packets.slice(-8):this.packets){if(this.visibleEdgeSet&&!this.visibleEdgeSet.has(packet.edge))continue;const progress=(now-packet.at)/duration;if(progress<0||progress>1)continue;const pos=this.point(packet.edge,packet.reverse?1-progress:progress);const color=packet.failed?[1,.32,.4]:packet.reverse?[.70,.56,1]:[.25,1,.84];const fade=Math.min(1,progress*12,(1-progress)*12);points.push(...pos,...color,(this.reduced?.85:.98)*fade,Math.max(22,28*Math.sqrt(this.zoom))*dpr);}
    if(points.length){gl.uniform1f(this.uPoint,1);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(points),gl.DYNAMIC_DRAW);gl.drawArrays(gl.POINTS,0,points.length/7);}
  }
  destroy(){cancelAnimationFrame(this.frame);if(this.gl){this.gl.deleteBuffer(this.buffer);this.gl.deleteProgram(this.program);this.gl.deleteBuffer(this.boxBuffer);this.gl.deleteProgram(this.boxProgram);}}
}
window.FlowRenderer=FlowRenderer;
